#include "nn.h"
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

int gs_dense_init(GsDense* l,int in,int out){if(!l||in<=0||out<=0)return 0;memset(l,0,sizeof(*l));l->input_size=in;l->output_size=out;l->weights=gs_tensor_rand(2,(int64_t[]){in,out},GS_FLOAT32);l->bias=gs_tensor_zeros(1,(int64_t[]){out},GS_FLOAT32);return l->weights&&l->bias;}
void gs_dense_free(GsDense*l){if(!l)return;gs_tensor_release(l->weights);gs_tensor_release(l->bias);memset(l,0,sizeof(*l));}
GsTensor*gs_dense_forward(const GsDense*l,const GsTensor*x,GsActivation act){if(!l||!x||x->ndim!=2||x->shape[1]!=l->input_size)return NULL;GsTensor*y=gs_tensor_matmul(x,l->weights);if(!y)return NULL;for(int64_t n=0;n<y->shape[0];n++)for(int j=0;j<l->output_size;j++){int64_t idx[2]={n,j};double v=gs_tensor_get_f64(y,idx)+gs_tensor_get_f64(l->bias,(int64_t[]){j});if(act==GS_ACT_RELU&&v<0)v=0;if(act==GS_ACT_SIGMOID)v=1/(1+exp(-v));if(act==GS_ACT_TANH)v=tanh(v);gs_tensor_set_f64(y,idx,v);}return y;}
double gs_train_dense_mse(GsDense*l,const GsTensor*x,const GsTensor*y,int epochs,double lr){if(!l||!x||!y||x->ndim!=2||y->ndim!=2||x->shape[0]!=y->shape[0]||x->shape[1]!=l->input_size||y->shape[1]!=l->output_size||epochs<=0||lr<=0)return -1;int n=(int)x->shape[0],in=l->input_size,out=l->output_size;GsTensor*gw=gs_tensor_zeros(2,(int64_t[]){in,out},GS_FLOAT32);GsTensor*gb=gs_tensor_zeros(1,(int64_t[]){out},GS_FLOAT32);if(!gw||!gb){gs_tensor_release(gw);gs_tensor_release(gb);return -1;}double loss=0;for(int ep=0;ep<epochs;ep++){gs_tensor_fill(gw,0);gs_tensor_fill(gb,0);loss=0;for(int r=0;r<n;r++)for(int j=0;j<out;j++){double pred=gs_tensor_get_f64(l->bias,(int64_t[]){j});for(int k=0;k<in;k++)pred+=gs_tensor_get_f64(x,(int64_t[]){r,k})*gs_tensor_get_f64(l->weights,(int64_t[]){k,j});double err=pred-gs_tensor_get_f64(y,(int64_t[]){r,j});loss+=err*err;gs_tensor_set_f64(gb,(int64_t[]){j},gs_tensor_get_f64(gb,(int64_t[]){j})+2*err/(n*out));for(int k=0;k<in;k++)gs_tensor_set_f64(gw,(int64_t[]){k,j},gs_tensor_get_f64(gw,(int64_t[]){k,j})+2*err*gs_tensor_get_f64(x,(int64_t[]){r,k})/(n*out));}for(int64_t i=0;i<l->weights->numel;i++)gs_tensor_set_f64(l->weights,(int64_t[]){i/out,i%out},gs_tensor_get_f64(l->weights,(int64_t[]){i/out,i%out})-lr*gs_tensor_get_f64(gw,(int64_t[]){i/out,i%out}));for(int j=0;j<out;j++)gs_tensor_set_f64(l->bias,(int64_t[]){j},gs_tensor_get_f64(l->bias,(int64_t[]){j})-lr*gs_tensor_get_f64(gb,(int64_t[]){j}));loss/=n*out;}gs_tensor_release(gw);gs_tensor_release(gb);return loss;}
int gs_dense_save(const GsDense*l,const char*path){if(!l||!path)return 0;FILE*f=fopen(path,"wb");if(!f)return 0;uint32_t magic=0x47534d31;int ok=fwrite(&magic,4,1,f)==1&&fwrite(&l->input_size,4,1,f)==1&&fwrite(&l->output_size,4,1,f)==1;for(int i=0;ok&&i<l->input_size;i++)for(int j=0;j<l->output_size;j++){double v=gs_tensor_get_f64(l->weights,(int64_t[]){i,j});ok=fwrite(&v,8,1,f)==1;}for(int j=0;ok&&j<l->output_size;j++){double v=gs_tensor_get_f64(l->bias,(int64_t[]){j});ok=fwrite(&v,8,1,f)==1;}if(fclose(f)!=0)ok=0;return ok;}
int gs_dense_load(GsDense*l,const char*path){if(!l||!path)return 0;FILE*f=fopen(path,"rb");if(!f)return 0;uint32_t magic;int in,out;if(fread(&magic,4,1,f)!=1||magic!=0x47534d31||fread(&in,4,1,f)!=1||fread(&out,4,1,f)!=1||in<=0||out<=0||in>100000||out>100000){fclose(f);return 0;}GsDense tmp;if(!gs_dense_init(&tmp,in,out)){fclose(f);return 0;}int ok=1;for(int i=0;ok&&i<in;i++)for(int j=0;j<out;j++){double v;if(fread(&v,8,1,f)!=1){ok=0;break;}gs_tensor_set_f64(tmp.weights,(int64_t[]){i,j},v);}for(int j=0;ok&&j<out;j++){double v;if(fread(&v,8,1,f)!=1){ok=0;break;}gs_tensor_set_f64(tmp.bias,(int64_t[]){j},v);}fclose(f);if(!ok){gs_dense_free(&tmp);return 0;}gs_dense_free(l);*l=tmp;return 1;}

int gs_dense_save_model(const GsDense*l,const char*p){return gs_dense_save(l,p);}
int gs_dense_load_model(GsDense*l,const char*p){return gs_dense_load(l,p);}

GsDataset*gs_dataset_load_numeric(const char*path,int input_size,int target_size){
    if(!path||input_size<=0||target_size<=0)return NULL;FILE*f=fopen(path,"r");if(!f)return NULL;
    int cols=input_size+target_size,rows=0,cap=128;double*data=malloc((size_t)cap*cols*sizeof(double));char*line=NULL;size_t linecap=0;ssize_t len;
    while((len=getline(&line,&linecap,f))>=0){char*p=line;double*row=malloc((size_t)cols*sizeof(double));int n=0;while(*p&&n<cols){while(*p&&!( (*p>='0'&&*p<='9')||*p=='-'||*p=='+'||*p=='.'))p++;if(!*p)break;char*end;errno=0;double v=strtod(p,&end);if(end==p){p++;continue;}if(errno==0)row[n++]=v;p=end;}if(n==cols){if(rows==cap){cap*=2;data=realloc(data,(size_t)cap*cols*sizeof(double));}memcpy(data+(size_t)rows*cols,row,(size_t)cols*sizeof(double));rows++;}free(row);}
    free(line);fclose(f);if(!rows){free(data);return NULL;}GsDataset*d=calloc(1,sizeof(*d));d->rows=rows;d->input_size=input_size;d->target_size=target_size;d->inputs=gs_tensor_create_2d(rows,input_size,GS_FLOAT32);d->targets=gs_tensor_create_2d(rows,target_size,GS_FLOAT32);if(!d->inputs||!d->targets){gs_dataset_free(d);free(data);return NULL;}for(int r=0;r<rows;r++){for(int c=0;c<input_size;c++)gs_tensor_set_f64(d->inputs,(int64_t[]){r,c},data[(size_t)r*cols+c]);for(int c=0;c<target_size;c++)gs_tensor_set_f64(d->targets,(int64_t[]){r,c},data[(size_t)r*cols+input_size+c]);}free(data);return d;
}
void gs_dataset_free(GsDataset*d){if(!d)return;gs_tensor_release(d->inputs);gs_tensor_release(d->targets);free(d);}
double gs_train_dense_dataset(GsDense*l,const GsDataset*d,int epochs,double lr){return d?gs_train_dense_mse(l,d->inputs,d->targets,epochs,lr):-1;}
